+import { DEFAULT_REALTIME_MODEL, type AgentStartConfig } from "../../../src/agent/src/index.js";
+import {
+  ParseCliArgs,
+  RunCli,
+  StartCliRuntime,
+  type CliRunDeps,
+} from "../../../src/agent/src/cli.js";
